package org.xipki.crypto.openssl;

import org.junit.Assert;
import org.junit.Test;

import javax.crypto.spec.DESKeySpec;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;

/**
 * The check of the DESede keys generated by {@link OsslSecretSpis.KeyGen}: the weak and
 * semi-weak DES keys, and the equal sub-keys.
 *
 * @author Lijun Liao (xipki)
 */
public class OsslDesedeKeyTest {

  private static final byte[] K1 = bytes(0x0123456789ABCDEFL);

  private static final byte[] K2 = bytes(0x23456789ABCDEF01L);

  private static final byte[] K3 = bytes(0x456789ABCDEF0123L);

  @Test
  public void testWeakKeyTable() throws Exception {
    // the 4 weak and 12 semi-weak keys, the same as in the JDK
    Set<Long> distinct = new HashSet<>();
    for (long weak : OsslSecretSpis.KeyGen.WEAK_DES_KEYS) {
      Assert.assertTrue(Long.toHexString(weak), DESKeySpec.isWeak(bytes(weak), 0));
      distinct.add(weak);
    }
    Assert.assertEquals(16, distinct.size());
  }

  @Test
  public void testValidKeys() {
    for (byte[] k : new byte[][]{K1, K2, K3}) {
      Assert.assertFalse(isWeak(k));
    }
    Assert.assertTrue(OsslSecretSpis.KeyGen.isValidDesedeKey(key(K1, K2, K3), false));
    Assert.assertTrue(OsslSecretSpis.KeyGen.isValidDesedeKey(key(K1, K2, K1), true));
  }

  @Test
  public void testInvalidKeys() {
    // equal sub-keys
    Assert.assertFalse(OsslSecretSpis.KeyGen.isValidDesedeKey(key(K1, K1, K3), false));
    Assert.assertFalse(OsslSecretSpis.KeyGen.isValidDesedeKey(key(K1, K2, K2), false));
    Assert.assertFalse(OsslSecretSpis.KeyGen.isValidDesedeKey(key(K1, K2, K1), false));
    Assert.assertFalse(OsslSecretSpis.KeyGen.isValidDesedeKey(key(K1, K1, K1), true));

    // a weak or semi-weak DES key at any position
    for (long weak : OsslSecretSpis.KeyGen.WEAK_DES_KEYS) {
      byte[] w = bytes(weak);
      Assert.assertFalse(OsslSecretSpis.KeyGen.isValidDesedeKey(key(w, K2, K3), false));
      Assert.assertFalse(OsslSecretSpis.KeyGen.isValidDesedeKey(key(K1, w, K3), false));
      Assert.assertFalse(OsslSecretSpis.KeyGen.isValidDesedeKey(key(K1, K2, w), false));
      Assert.assertFalse(OsslSecretSpis.KeyGen.isValidDesedeKey(key(w, K2, w), true));
    }
  }

  private static boolean isWeak(byte[] k) {
    try {
      return DESKeySpec.isWeak(k, 0);
    } catch (Exception e) {
      throw new IllegalStateException(e);
    }
  }

  private static byte[] key(byte[] k1, byte[] k2, byte[] k3) {
    byte[] key = Arrays.copyOf(k1, 24);
    System.arraycopy(k2, 0, key, 8, 8);
    System.arraycopy(k3, 0, key, 16, 8);
    return key;
  }

  private static byte[] bytes(long v) {
    byte[] b = new byte[8];
    for (int i = 7; i >= 0; i--) {
      b[i] = (byte) v;
      v >>>= 8;
    }
    return b;
  }

}
